style.css:
@-moz-document url("https://www.duboku.tv/") {
/* 1. Background Styling */
    body {
        background-image: url('https://i.pinimg.com/736x/df/57/2d/df572d0ad42d0a6430d101f06b03ffde.jpg') !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        margin: 0 !important;
        padding: 0 !important;
        font-family: Arial, sans-serif !important;
        color: white !important;
        overflow-x: hidden !important; /* Prevent horizontal scrolling */
    }

    /* 2. Ensure full transparency for all elements */
    * {
        background-color: transparent !important;
        border: none !important;
        box-shadow: none !important;
        outline: none !important; /* Remove outlines */
        color: inherit !important; /* Inherit text color */
        text-shadow: none !important;
    }

    /* 3. Video Player and Main Content Area */
    .video-container, .vod-player, #player-container, .content-wrapper, .main-content {
        background-color: transparent !important;
        border: none !important;
        box-shadow: none !important;
        padding: 0 !important;
        margin: 0 !important;
    }

    /* 4. Comment Section, Sidebar, Footer */
    .comment-section, .comments-container, .sidebar, #footer {
        background-color: transparent !important;
        box-shadow: none !important;
        border: none !important;
        padding: 0 !important;
        margin: 0 !important;
    }

    /* 5. Header */
    #header {
        background-color: transparent !important;
        color: white !important;
        border-bottom: none !important;
    }

    /* 6. Links */
    a {
        color: pink !important;
        text-decoration: none !important;
        transition: color 0.3s ease-in-out !important;
    }

    a:hover {
        color: #ff69b4 !important; /* Lighter pink for hover effect */
    }

    /* 7. Progress Bar - Set to pink with transparency */
    progress {
        width: 100% !important;
        height: 10px !important;
        border-radius: 5px !important;
        appearance: none !important;
        -webkit-appearance: none !important;
        -moz-appearance: none !important;
        background-color: rgba(0, 0, 0, 0.5) !important; /* Transparent background */
    }

    progress::-webkit-progress-bar {
        background-color: rgba(0, 0, 0, 0.5) !important;
    }

    progress::-webkit-progress-value {
        background-color: pink !important; /* Pink progress bar */
    }

    progress::-moz-progress-bar {
        background-color: pink !important; /* Pink progress bar for Firefox */
    }

    /* 8. Video Controls - Set to pink */
    .video-controls .icon, .video-controls .fa, .video-controls button, .video-controls img {
        color: pink !important;
        transition: color 0.3s ease-in-out !important;
    }

    /* 9. Video Controls Hover Effect */
    .video-controls .icon:hover, .video-controls .fa:hover, .video-controls img:hover, .video-controls button:hover {
        color: #ff69b4 !important; /* Light pink on hover */
    }

    /* 10. Text Shadow for Improved Readability */
    h1, h2, h3, p, a, .video-title, .comments-text {
        color: white !important;
        text-shadow: 2px 2px 6px rgba(0, 0, 0, 0.7) !important;
    }

    /* 11. Video Controls and Buttons - No borders and transparent background */
    .video-controls, .video-container, .vod-player, .comment-section {
        background-color: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }

    /* 12. Customizing Video Player Appearance */
    .vod-player video {
        border-radius: 10px !important; /* Rounded corners for video */
        width: 100% !important;
        height: auto !important;
    }

    /* 13. Customizing the Sidebar */
    .sidebar {
        background-color: transparent !important;
        box-shadow: none !important;
        padding: 0 !important;
    }

    /* 14. Customizing the Player Controls */
    .player-controls {
        background-color: transparent !important;
        box-shadow: none !important;
        border: none !important;
    }

    /* 15. Customizing Comment Boxes */
    .comment-box {
        background-color: transparent !important;
        border: 1px solid rgba(255, 255, 255, 0.5) !important;
        color: white !important;
        box-shadow: none !important;
    }

    .comment-box textarea {
        background-color: transparent !important;
        border: 1px solid rgba(255, 255, 255, 0.3) !important;
        color: white !important;
    }

    /* 16. Ensure Transparent Background for All Popups or Overlays */
    .popup-overlay, .modal-background, .fullscreen-overlay {
        background-color: rgba(0, 0, 0, 0.4) !important; /* Dark transparent background for popups */
    }

    /* 17. Navigation Bar */
    .nav-bar {
        background-color: transparent !important;
        color: white !important;
        box-shadow: none !important;
        border: none !important;
    }

    .nav-bar a {
        color: pink !important;
        transition: color 0.3s ease !important;
    }

    .nav-bar a:hover {
        color: #ff69b4 !important;
    }

    /* 18. Custom Styling for Media Queries (Optional for smaller screens) */
    @media (max-width: 768px) {
        .video-container {
            padding: 10px !important;
        }

        .vod-player {
            height: 300px !important;
        }

        .sidebar {
            display: none !important; /* Hide sidebar on mobile */
        }
    }
}
